var findSubsequences = function(nums) {
    const res = [];
    const path = [];

    function backtrack(start) {
        if (path.length >= 2) {
            res.push([...path]);
        }
        const used = new Set();
        for (let i = start; i < nums.length; i++) {
            if (used.has(nums[i])) continue;
            if (path.length === 0 || nums[i] >= path[path.length - 1]) {
                used.add(nums[i]);
                path.push(nums[i]);
                backtrack(i + 1);
                path.pop();
            }
        }
    }

    backtrack(0);
    return res;
};
